// TestPostFeedbackHonorsConfiguredTimeout guards against a regression to
// the old hardcoded `client := &http.Client{Timeout: 15 * time.Second}`,
// which ignored the user's --timeout flag entirely. A slow endpoint plus a
// short configured timeout must fail fast (well under 15s), proving the
// timeout parameter -- not a fixed constant -- governs the request.
func TestPostFeedbackHonorsConfiguredTimeout(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(500 * time.Millisecond)
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(server.Close)

	entry := FeedbackEntry{Text: "slow endpoint test", CLI: "quickcommerce-pp-cli"}
	start := time.Now()
	err := postFeedback(context.Background(), server.URL, entry, 20*time.Millisecond)
	elapsed := time.Since(start)

	if err == nil {
		t.Fatal("expected a timeout error from postFeedback, got nil")
	}
	if elapsed > 300*time.Millisecond {
		t.Fatalf("postFeedback took %v; want it bounded by the 20ms configured timeout, not a hardcoded 15s default", elapsed)
	}
}

// TestPostFeedbackRespectsCanceledContext confirms the request is actually
// wired to the passed context (http.NewRequestWithContext), not just a
// client-level timer -- a canceled context must abort immediately.
func TestPostFeedbackRespectsCanceledContext(t *testing.T) {
	t.Parallel()

	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(time.Second)
		w.WriteHeader(http.StatusOK)
	}))
	t.Cleanup(server.Close)

	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	entry := FeedbackEntry{Text: "canceled context test", CLI: "quickcommerce-pp-cli"}
	start := time.Now()
	err := postFeedback(ctx, server.URL, entry, time.Second)
	elapsed := time.Since(start)

	if err == nil {
		t.Fatal("expected an error from postFeedback with a pre-canceled context, got nil")
	}
	if elapsed > 300*time.Millisecond {
		t.Fatalf("postFeedback took %v; a pre-canceled context should abort immediately", elapsed)
	}
}
